type Modal={type:'group'}|{type:'expense';groupId:string;expense?:Expense}|{type:'settle';groupId:string;from?:string;to?:string;amount?:number}|{type:'settings';groupId:string}|{type:'import';groupId:string}|{type:'invite';groupId:string}|{type:'delete';groupId:string;expenseId:string}|null;
function err(e:unknown){return e instanceof Error?e.message:'Something went wrong. Please try again.'}
function Icon({category}:{category:string}){const icons:Record<string,string>={'Food & drink':'🍜',Travel:'✈️',Home:'🏡',Groceries:'🥑',Entertainment:'🎟️',Shopping:'🛍️',Utilities:'⚡',Other:'🧾'};return <span className={'expense-icon cat-'+category.split(' ')[0].toLowerCase()}>{icons[category]||'🧾'}</span>}
function Logo(){return <span className="logo"><span className="logo-icon"><svg width="23" height="23" viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M7 7h14M7 14h9M7 21h5" stroke="currentColor" strokeWidth="3" strokeLinecap="round"/><path d="m17 18 3 3 5-6" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg></span>fairshare<span className="logo-dot">.</span></span>}
function Avatar({name,index=0,small=false}:{name:string;index?:number;small?:boolean}){return <span className={`avatar avatar-${index%5} ${small?'avatar-small':''}`}>{name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase()}</span>}
function ModalShell({title,eyebrow,children,onClose,wide=false}:{title:string;eyebrow?:string;children:ReactNode;onClose:()=>void;wide?:boolean}){useEffect(()=>{const old=document.body.style.overflow;document.body.style.overflow='hidden';const f=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const dialog=document.querySelector('.modal');const nodes=dialog?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',f);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',f)}},[]);return <div className="modal-backdrop"><section className={`modal ${wide?'modal-wide':''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h2 id="modal-title">{title}</h2></div><button autoFocus className="icon-btn" aria-label="Close dialog" onClick={onClose}><X size={20}/></button></header>{children}</section></div>}
export default function App(){const [data,setData]=useState<Workspace|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[tab,setTab]=useState('Overview'),[selected,setSelected]=useState<string|null>(null),[modal,setModal]=useState<Modal>(null),[query,setQuery]=useState(''),[currency,setCurrency]=useState('USD'),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[dark,setDark]=useState(()=>localStorage.getItem('fairshare-dark')==='true'),[period,setPeriod]=useState('All time');
async function load(){try{const result=await api<Workspace>('/workspace');setData(result);setError('')}catch(e){setError(err(e))}finally{setLoading(false)}}useEffect(()=>{load();const timer=setInterval(load,60000);return()=>clearInterval(timer)},[]);useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('fairshare-dark',String(dark))},[dark]);useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t)},[toast]);useEffect(()=>{if(!data)return;const token=new URLSearchParams(location.search).get('invite')||sessionStorage.getItem('letstalkmoney-invite');if(token){api('/join',{token}).then(()=>{history.replaceState({},'',location.pathname);sessionStorage.removeItem('letstalkmoney-invite');setToast('You joined the group.');load()}).catch(e=>setError(err(e))) }},[!!data]);
const groups=data?.groups||[],user=data?.user,group=groups.find(g=>g.id===selected);const scope=group?[group]:groups.filter(g=>g.currency===currency);const allRows=scope.flatMap(g=>g.expenses.map(e=>({g,e}))).sort((a,b)=>b.e.date.localeCompare(a.e.date)||b.e.createdAt.localeCompare(a.e.createdAt));const rows=allRows.filter(({g,e})=>(!query||`${e.description} ${e.category} ${e.notes} ${g.name} ${g.members.find(m=>m.id===e.payer)?.name}`.toLowerCase().includes(query.toLowerCase()))&&(period==='All time'||e.date.startsWith(today().slice(0,7))));const displayCurrency=group?.currency||currency;const mine=(g:Group)=>g.members.find(m=>m.userId===user?.id)?.id||'';const positive=scope.reduce((s,g)=>s+Math.max(0,balances(g)[mine(g)]||0),0),negative=scope.reduce((s,g)=>s+Math.max(0,-(balances(g)[mine(g)]||0)),0);const personalShare=rows.reduce((s,{g,e})=>s+(e.splits[mine(g)]||0),0);const totalSpent=rows.reduce((s,{e})=>s+e.baseAmount,0);const activeGroup=group||groups[0];
async function mutate(g:Group,payload:any,notice:string){setBusy(true);try{const result=await api<Group>(`/groups/${g.id}`,{...payload,revision:g.revision});setData(d=>d?{...d,groups:d.groups.map(x=>x.id===g.id?result:x)}:d);setToast(notice);setModal(null)}catch(e){throw e}finally{setBusy(false)}}
function requireGroup(type:'expense'|'settle'|'import'|'settings'|'invite'){if(!activeGroup){setModal({type:'group'});return}setModal({type,groupId:activeGroup.id} as Modal)}
function go(name:string){setTab(name);setSelected(null);setQuery('')}
function exportCSV(){const records=rows.map(({g,e})=>({date:e.date,description:e.description,group:g.name,category:e.category,original_amount:(e.amount/100).toFixed(2),original_currency:e.currency,group_amount:(e.baseAmount/100).toFixed(2),group_currency:g.currency,paid_by:g.members.find(m=>m.id===e.payer)?.name||'',your_share:((e.splits[mine(g)]||0)/100).toFixed(2),notes:e.notes}));download('fairshare-expenses.csv',Papa.unparse<Record<string,string>>(records.length?records:[{date:'',description:'',group:'',amount:''}]),'text/csv')}
if(!data&&loading)return <div className="loading-screen"><Logo/><LoaderCircle className="spin" size={25}/><p>Getting your balances in order…</p></div>;
if(!data)return <div className="loading-screen"><Logo/><h1>Let’s open your workspace.</h1><p>{error}</p><button className="primary" onClick={()=>signIn().catch(e=>setError(err(e)))}>Continue with Google <ArrowRight size={16}/></button><p className="quiet-note">Use your Google account to create groups or accept an invitation.</p><button className="text-btn" onClick={load}>Try again</button></div>;
return <div className="app-shell"><aside className="sidebar"><button className="brand-button" onClick={()=>go('Overview')}><Logo/></button><span className="workspace-badge"><span/> PERSONAL WORKSPACE <ChevronDown size={12}/></span><nav aria-label="Main navigation">{[[LayoutDashboard,'Overview'],[Users,'Groups'],[Receipt,'All expenses'],[ChartNoAxesCombined,'Insights'],[Activity,'Activity']].map(([I,label])=>{const Icon=I as typeof Receipt;return <button key={String(label)} className={!selected&&tab===label?'active':''} onClick={()=>go(String(label))}><Icon size={18}/><span>{String(label)}</span>{label==='Groups'&&<small>{groups.length}</small>}</button>})}</nav><div className="sidebar-section"><span>YOUR GROUPS</span><button aria-label="Create group" onClick={()=>setModal({type:'group'})}><Plus size={16}/></button></div><div className="group-nav">{groups.map(g=><button key={g.id} className={selected===g.id?'active':''} onClick={()=>{setSelected(g.id);setTab('Overview');setQuery('')}}><span className="group-emoji"><GroupIcon group={g}/></span><span>{g.name}</span>{(balances(g)[mine(g)]||0)!==0&&<i/>}</button>)}{groups.length===0&&<p>Your next shared adventure starts here.</p>}</div><div className="sidebar-bottom"><div className="little-note"><span className="note-stars">✳</span><strong>Less math.<br/>More good times.</strong><p>No ads. No daily limits.</p></div><button className="profile" onClick={()=>setDark(v=>!v)}><Avatar name={data.user.name}/><span><strong>{data.user.name}</strong><small>{demo?'Demo workspace':'Your private workspace'}</small></span>{dark?<Sun size={16}/>:<Moon size={16}/>}</button></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb">Workspace <ChevronRight size={13}/><strong>{group?.name||tab}</strong></div><div className="topbar-actions"><span className="live-status"><span/> {busy?'Saving…':demo?'Preview workspace':'Cloud workspace'}</span><button className="icon-btn" aria-label="Refresh workspace" onClick={load}><RefreshCw size={16}/></button><button className="icon-btn mobile-theme" aria-label="Toggle color theme" onClick={()=>setDark(v=>!v)}>{dark?<Sun size={17}/>:<Moon size={17}/>}</button><Avatar name={data.user.name} small/>{!demo&&<button className="icon-btn" aria-label="Sign out" onClick={()=>signOut()}><LogOut size={17}/></button>}</div></header>{demo&&<div className="demo-strip">Interactive preview · Sample expenses stay in this browser. Your hosted workspace uses private cloud storage.</div>}<main className="main-content">{error&&<div className="error-banner" role="alert">{error}<button onClick={load}>Retry</button></div>}{toast&&<div className="toast" role="status"><CheckCircle2 size={17}/>{toast}</div>}
{group?.banner&&<div className="group-detail-banner" style={{backgroundImage:`url(${group.banner})`}}/>}<div className="page-heading"><div><span className="eyebrow">{group?'SHARED MOMENTS, SORTED':'GOOD FRIENDS. CLEAR BALANCES.'}</span><h1>{group?<><span className="group-title-emoji"><GroupIcon group={group}/></span>{group.name}</>:tab==='Overview'?<>A little clarity goes a long way<span className="heading-period">.</span></>:tab==='Groups'?'Better together.':tab==='Insights'?'The bigger picture.':tab==='Activity'?'Nothing gets lost.':'Every little detail.'}</h1><p>{group?`${group.members.length} members · ${group.currency} · ${group.expenses.length} shared expenses`:tab==='Overview'?`Here’s where things stand, ${data.user.name.split(' ')[0]}. Let’s keep life balanced.`:tab==='Groups'?'Trips, homes, dinners, and everything you share.':tab==='Insights'?'Understand your spending, one shared moment at a time.':tab==='Activity'?'A clear record of expenses, payments, and changes.':'Search, review, and organize all your shared expenses.'}</p></div><div className="heading-actions">{group&&<button className="secondary icon-only" aria-label="Group settings" onClick={()=>requireGroup('settings')}><Settings size={17}/></button>}<button className="primary" onClick={()=>tab==='Groups'&&!group?setModal({type:'group'}):requireGroup('expense')}><Plus size={17}/>{tab==='Groups'&&!group?'Create group':'Add expense'}</button></div></div>
{!group&&tab!=='Groups'&&<div className="view-controls"><label className="currency-control">DISPLAYING <select aria-label="Dashboard currency" value={currency} onChange={e=>setCurrency(e.target.value)}>{currencies.map(c=><option key={c}>{c}</option>)}</select><span>Balances stay separate by currency</span></label><button className="text-btn" onClick={exportCSV}><Download size={14}/>Export CSV</button></div>}
{(tab==='Overview'||group)&&<><section className="balance-grid"><div className="balance-card balance-main"><div className="card-label">YOUR TOTAL BALANCE <span className="card-symbol">↗</span></div><strong>{money(positive-negative,displayCurrency)}</strong><div className="balance-foot"><span className="balance-dot"/> {positive-negative>=0?'Looking good. You’re ahead.':'A few things to settle.'}<button onClick={()=>requireGroup('settle')}>Settle up <ArrowUpRight size={14}/></button></div><div className="balance-orbit" aria-hidden="true"/></div><div className="balance-card"><div className="card-label">YOU ARE OWED <span className="metric-icon owed"><ArrowDownLeft size={17}/></span></div><strong className="positive">{money(positive,displayCurrency)}</strong><div className="card-footnote">From the good people in your groups</div></div><div className="balance-card"><div className="card-label">YOU OWE <span className="metric-icon owe"><ArrowUpRight size={17}/></span></div><strong className="negative">{money(negative,displayCurrency)}</strong><div className="card-footnote">A little settling goes a long way</div></div></section>
{!group&&<section className="groups-section"><div className="section-title"><h2>Your groups <span>{groups.length}</span></h2><button className="text-btn" onClick={()=>go('Groups')}>View all groups <ArrowRight size={14}/></button></div><div className="group-cards">{groups.slice(0,3).map((g,i)=><GroupCard key={g.id} group={g} index={i} myId={mine(g)} onClick={()=>setSelected(g.id)}/>)}<button className="new-group-card" onClick={()=>setModal({type:'group'})}><span><Plus size={22}/></span><strong>A new shared chapter</strong><small>Create a group</small></button></div></section>}
{group&&<div className="group-tools"><div className="avatar-stack">{group.members.map((m,i)=><span key={m.id} title={m.name}><Avatar name={m.name} index={i} small/></span>)}<button className="add-member-btn" aria-label="Manage group members" onClick={()=>requireGroup('settings')}><Plus size={14}/></button></div><div><button className="text-btn" onClick={()=>requireGroup('invite')}><Link size={14}/>Invite people</button><button className="text-btn" onClick={()=>requireGroup('import')}><FileUp size={14}/>Import transactions</button><button className="secondary" onClick={()=>requireGroup('settle')}><ArrowLeftRight size={15}/>Settle up</button></div></div>}
<div className="dashboard-columns"><section className="expenses-panel"><div className="section-title"><h2>Recent expenses</h2><span className="subtle-label">A little of everything you’ve shared</span></div><ExpenseToolbar query={query} setQuery={setQuery} period={period} setPeriod={setPeriod}/><ExpenseList rows={rows.slice(0,group?rows.length:8)} myId={mine} onEdit={(g,e)=>setModal({type:'expense',groupId:g.id,expense:e})}/>{!group&&rows.length>8&&<button className="panel-footer-button" onClick={()=>{setTab('All expenses')}}>View all {rows.length} expenses <ArrowRight size={15}/></button>}</section><aside className="right-rail"><div className="spending-card"><div className="section-title"><h2>Your spending</h2><ChartNoAxesCombined size={17}/></div><span className="tiny-label">YOUR SHARE · {period.toUpperCase()}</span><strong>{money(personalShare,displayCurrency)}</strong><SpendingChart rows={rows.map(({g,e})=>({g,e:{...e,baseAmount:e.splits[mine(g)]||0}}))} currency={displayCurrency}/><button className="text-btn" onClick={()=>{setSelected(null);setTab('Insights')}}>Explore insights <ArrowRight size={14}/></button></div><div className="settlement-card"><div className="section-title"><h2>Keep it simple</h2><ArrowLeftRight size={16}/></div><p>Fewer payments. Same fair result.</p>{scope.flatMap(g=>simplify(g).filter(s=>s.from===mine(g)||s.to===mine(g)).map(s=>({g,s}))).slice(0,3).map(({g,s},i)=><button className="suggestion" key={g.id+i} onClick={()=>setModal({type:'settle',groupId:g.id,...s})}><Avatar name={g.members.find(m=>m.id===(s.from===mine(g)?s.to:s.from))?.name||''} index={i+1} small/><span><strong>{s.from===mine(g)?'Pay':'Receive from'} {g.members.find(m=>m.id===(s.from===mine(g)?s.to:s.from))?.name}</strong><small>{g.name}</small></span><b className={s.from===mine(g)?'negative':'positive'}>{money(s.amount,g.currency)}</b></button>)}{scope.every(g=>!simplify(g).some(s=>s.from===mine(g)||s.to===mine(g)))&&<div className="all-clear"><CheckCheck size={23}/><span>All square. Good feeling, right?</span></div>}</div></aside></div></>}
{tab==='Groups'&&!group&&<section className="all-groups-grid">{groups.map((g,i)=><GroupCard key={g.id} group={g} index={i} myId={mine(g)} onClick={()=>{setSelected(g.id);setTab('Overview')}}/>)}<button className="new-group-card" onClick={()=>setModal({type:'group'})}><span><Plus size={24}/></span><strong>Create a new group</strong><small>Make room for the next plan</small></button></section>}
{tab==='All expenses'&&!group&&<section className="expenses-panel"><div className="section-title"><h2>All expenses <span>{rows.length}</span></h2><button className="text-btn" onClick={()=>requireGroup('import')}><FileUp size={14}/>Import CSV</button></div><ExpenseToolbar query={query} setQuery={setQuery} period={period} setPeriod={setPeriod}/><ExpenseList rows={rows} myId={mine} onEdit={(g,e)=>setModal({type:'expense',groupId:g.id,expense:e})}/></section>}
{tab==='Insights'&&!group&&<><div className="insight-totals"><div><span>GROUP SPENDING</span><strong>{money(totalSpent,currency)}</strong></div><div><span>YOUR SHARE</span><strong>{money(personalShare,currency)}</strong></div><div><span>EXPENSES TRACKED</span><strong>{rows.length}</strong></div></div><div className="insights-grid"><section className="expenses-panel insight-panel"><div className="section-title"><h2>Where it all goes</h2><select aria-label="Insights date range" value={period} onChange={e=>setPeriod(e.target.value)}><option>All time</option><option>This month</option></select></div><CategoryChart rows={rows} currency={currency}/></section><section className="expenses-panel insight-panel"><div className="section-title"><h2>Spending over time</h2><span className="tiny-label">LAST 6 MONTHS</span></div><TrendChart rows={rows} currency={currency}/></section></div><section className="expenses-panel budgets"><div className="section-title"><h2>Group budgets</h2><span className="tiny-label">TOTAL GROUP SPENDING</span></div>{scope.map(g=>{const spent=g.expenses.reduce((a,e)=>a+e.baseAmount,0);return <button key={g.id} className="budget-row" onClick={()=>setModal({type:'settings',groupId:g.id})}><span><GroupIcon group={g}/></span><div><strong>{g.name}</strong><div className="progress-track"><i style={{width:`${g.budget?Math.min(100,spent/g.budget*100):0}%`}} className={spent>g.budget&&g.budget?'over-budget':''}/></div></div><span>{money(spent,g.currency)} <small>/ {g.budget?money(g.budget,g.currency):'No budget set'}</small></span><ChevronRight size={17}/></button>})}{!scope.length&&<Empty title="A fresh perspective is on its way." text="Add your first expense to see your spending patterns."/>}</section></>}
{tab==='Activity'&&!group&&<section className="expenses-panel activity-panel"><div className="section-title"><h2>Your shared story</h2></div>{groups.flatMap(g=>g.activity.map(a=>({...a,group:g}))).sort((a,b)=>b.date.localeCompare(a.date)).map(a=><div className="activity-row" key={a.id}><span className="activity-icon"><Activity size={17}/></span><div><strong>{a.text}</strong><small>{a.group.name} · {new Date(a.date).toLocaleString()}</small></div><Check size={14}/></div>)}{groups.every(g=>!g.activity.length)&&<Empty title="A clean slate." text="Your expenses, edits, and settlements will appear here."/>}</section>}
<footer className="app-footer"><span><Leaf size={13}/> A little fairness makes room for a lot of living.</span><span>Built for sharing. Designed for peace of mind.</span></footer></main></div>
{modal&&<Dialogs modal={modal} setModal={setModal} groups={groups} user={data.user} busy={busy} mutate={mutate} onGroup={g=>{setData(d=>d?{...d,groups:[g,...d.groups]}:d);setSelected(g.id);setTab('Overview');setModal(null);setToast('Your group is ready. Good things ahead.')}} onToast={setToast}/>}</div>}
function GroupCard({group:g,index,myId,onClick}:{group:Group;index:number;myId:string;onClick:()=>void}){const b=balances(g)[myId]||0;return <button className={`group-card group-style-${index%4}`} onClick={onClick}><div className="group-cover" style={{background:g.banner?`url(${g.banner}) center / cover`:g.bannerColor||'#cddbc2'}}><span className="group-cover-emoji"><GroupIcon group={g}/></span><span className="cover-tag">{g.members.length} people</span></div><div className="group-card-body"><h3>{g.name}<ArrowUpRight size={15}/></h3><div className="group-card-bottom"><div className="avatar-stack">{g.members.slice(0,3).map((m,i)=><Avatar key={m.id} name={m.name} index={i} small/>)}</div><span className={b>0?'positive':b<0?'negative':'muted'}>{b>0?'you get back':b<0?'you owe':'all settled'}<strong>{b!==0?money(Math.abs(b),g.currency):'All square ✓'}</strong></span></div></div></button>}
function ExpenseToolbar({query,setQuery,period,setPeriod}:{query:string;setQuery:(s:string)=>void;period:string;setPeriod:(s:string)=>void}){return <div className="expense-toolbar"><label className="search-field"><Search size={16}/><input aria-label="Search expenses" placeholder="Search expenses, people, or notes…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Clear search" onClick={()=>setQuery('')}><X size={14}/></button>}</label><label className="period-filter"><Calendar size={14}/><select aria-label="Expense date range" value={period} onChange={e=>setPeriod(e.target.value)}><option>All time</option><option>This month</option></select></label></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="empty"><span><Receipt size={27}/></span><h3>{title}</h3><p>{text}</p></div>}
function ExpenseList({rows,myId,onEdit}:{rows:{g:Group;e:Expense}[];myId:(g:Group)=>string;onEdit:(g:Group,e:Expense)=>void}){return <>{!rows.length?<Empty title="Nothing to split. Yet." text="Add an expense, or try a different search."/>:<><div className="expense-table-head"><span>EXPENSE</span><span>AMOUNT</span><span>YOUR SHARE</span><span/></div>{rows.map(({g,e})=><button className="expense-row" key={g.id+e.id} onClick={()=>onEdit(g,e)}><Icon category={e.category}/><span className="expense-description"><strong>{e.description}{e.repeat!=='none'&&<Repeat size={12}/>}</strong><small>{g.name}<i/> {new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})} <i/> {g.members.find(m=>m.id===e.payer)?.name||'Someone'} paid</small></span><span className="expense-amount"><strong>{money(e.baseAmount,g.currency)}</strong>{e.currency!==g.currency&&<small>{money(e.amount,e.currency)}</small>}</span><span className="expense-share">{money(e.splits[myId(g)]||0,g.currency)}</span><ChevronRight size={15}/></button>)}</>}</>}
const chartColors=['#507765','#bba2cf','#d8b88a','#8faec4','#a9bd80','#d9a5a0','#7b9ca0','#b5b9c6'];
function SpendingChart({rows,currency}:{rows:{g:Group;e:Expense}[];currency:string}){const buckets=categories.map((c,i)=>({name:c,amount:rows.filter(x=>x.e.category===c).reduce((s,x)=>s+x.e.baseAmount,0),color:chartColors[i]})).filter(x=>x.amount);const total=buckets.reduce((s,b)=>s+b.amount,0);return <div className="mini-chart"><div className="stacked-bar">{buckets.map(b=><span key={b.name} style={{width:`${b.amount/total*100}%`,background:b.color}} title={`${b.name}: ${money(b.amount,currency)}`}/>)}</div><div className="chart-legend">{buckets.slice(0,3).map(b=><div key={b.name}><i style={{background:b.color}}/><span>{b.name}</span><strong>{Math.round(b.amount/total*100)}%</strong></div>)}{!total&&<p>Add an expense to see the picture.</p>}</div></div>}
function CategoryChart({rows,currency}:{rows:{g:Group;e:Expense}[];currency:string}){const total=rows.reduce((a,r)=>a+r.e.baseAmount,0);let position=0;const values=categories.map((c,i)=>{const amount=rows.filter(r=>r.e.category===c).reduce((a,r)=>a+r.e.baseAmount,0),start=position;position+=total?amount/total*100:0;return {c,amount,start,end:position,color:chartColors[i]}}).filter(r=>r.amount);return <div className="category-visual"><div className="donut" style={{background:total?`conic-gradient(${values.map(v=>`${v.color} ${v.start}% ${v.end}%`).join(',')})`:'var(--line)'}}><div><span>TOTAL SPENT</span><strong>{money(total,currency)}</strong></div></div><div className="category-breakdown">{values.map(v=><div key={v.c}><i style={{background:v.color}}/><span>{v.c}</span><strong>{money(v.amount,currency)}</strong></div>)}</div></div>}
function TrendChart({rows,currency}:{rows:{g:Group;e:Expense}[];currency:string}){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);const key=d.toISOString().slice(0,7);return {label:d.toLocaleDateString('en-US',{month:'short'}),value:rows.filter(r=>r.e.date.startsWith(key)).reduce((a,r)=>a+r.e.baseAmount,0)}}),max=Math.max(1,...months.map(m=>m.value));return <div className="trend-chart">{months.map((m,i)=><div key={i}><span>{m.value?money(m.value,currency):'—'}</span><div className="trend-track"><i style={{height:`${Math.max(2,m.value/max*100)}%`}}/></div><small>{m.label}</small></div>)}</div>}
function download(name:string,content:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
