function GroupSettings({group:g,user,close,busy,error,save}:{group:Group;user:Workspace['user'];close:()=>void;busy:boolean;error:string;save:(p:any,n:string)=>Promise<void>}){const [name,setName]=useState(g.name),[emoji,setEmoji]=useState(g.emoji),[icon,setIcon]=useState(g.icon||''),[banner,setBanner]=useState(g.banner||''),[bannerColor,setBannerColor]=useState(g.bannerColor||'#cddbc2'),[budget,setBudget]=useState(g.budget?String(g.budget/100):''),[defaults,setDefaults]=useState<Record<string,number>>(Object.keys(g.defaults).length?g.defaults:Object.fromEntries(g.members.map(m=>[m.id,1]))),[memberName,setMemberName]=useState(''),[email,setEmail]=useState('');const owner=g.owner===user.id;return <ModalShell title="Make this group yours." eyebrow="GROUP SETTINGS" onClose={close}><form onSubmit={e=>{e.preventDefault();save({action:'settings',name,emoji,icon,banner,bannerColor,budget:budget?cents(budget):0,defaults},'Group preferences saved.')}}><div className="form-grid"><label>Group name<input required maxLength={80} value={name} disabled={!owner} onChange={e=>setName(e.target.value)}/></label><label>Fallback initials<input value={emoji} maxLength={10} disabled={!owner} onChange={e=>setEmoji(e.target.value)}/></label></div><ImageEditor label="Group icon" value={icon} setValue={setIcon} disabled={!owner}/><ImageEditor label="Group banner" value={banner} setValue={setBanner} disabled={!owner} wide/><label>Banner background<input type="color" value={bannerColor} disabled={!owner} onChange={e=>setBannerColor(e.target.value)}/></label><label>Budget ({g.currency})<input type="number" min="0" step="0.01" value={budget} disabled={!owner} onChange={e=>setBudget(e.target.value)}/></label><h3 className="form-heading">Default split shares</h3><p className="dialog-description">Use 1 and 1 for equal shares, or 55 and 45 for a 55/45 split. New expenses start with these defaults; old expenses stay unchanged.</p>{g.members.map((m,i)=><label className="default-share" key={m.id}><Avatar name={m.name} index={i} small/><span>{m.name}</span><input aria-label={`${m.name} default shares`} type="number" min="0" step="any" value={defaults[m.id]??1} disabled={!owner} onChange={e=>setDefaults(s=>({...s,[m.id]:Number(e.target.value)}))}/><span>shares</span></label>)}{error&&<Notice>{error}</Notice>}<div className="modal-footer"><button className="secondary" type="button" onClick={close}>Close</button><button className="primary" disabled={busy||!owner}><Check size={16}/>Save settings</button></div></form><div className="add-member-section"><h3 className="form-heading">Add someone to the group</h3><form onSubmit={e=>{e.preventDefault();save({action:'member',name:memberName,email},'Member added. Create an invitation link to connect their account.')}}><div className="form-grid"><label>Name<input required value={memberName} maxLength={80} disabled={!owner} onChange={e=>setMemberName(e.target.value)}/></label><label>Email, optional<input type="email" value={email} disabled={!owner} onChange={e=>setEmail(e.target.value)}/></label></div><button className="secondary" disabled={busy||!owner||!memberName.trim()}><Plus size={15}/>Add member</button></form></div></ModalShell>}
function InviteForm({group:g,close,onToast}:{group:Group;close:()=>void;onToast:(s:string)=>void}){const [memberId,setMember]=useState(g.members.find(m=>!m.userId)?.id||''),[link,setLink]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <ModalShell title="Good company, connected." eyebrow="INVITE A MEMBER" onClose={close}><p className="dialog-description">Link a person in your ledger to their own signed-in account. Share the invitation yourself; no email is sent.</p><label>Choose a member<select value={memberId} onChange={e=>{setMember(e.target.value);setLink('')}}>{g.members.filter(m=>!m.userId).map(m=><option key={m.id} value={m.id}>{m.name}{m.email?` (${m.email})`:''}</option>)}</select></label><button className="primary full-width" disabled={!memberId||busy||demo} onClick={async()=>{setBusy(true);try{const r=await api(`/groups/${g.id}/invite`,{memberId});setLink(r.url);setError('')}catch(e){setError(err(e))}finally{setBusy(false)}}}><Link size={16}/>{busy?'Creating link…':'Create invitation link'}</button>{link&&<label className="invite-link">Invitation link<div><input readOnly value={link} aria-label="Invitation link"/><button className="secondary" onClick={async()=>{try{await navigator.clipboard.writeText(link);onToast('Invitation link copied.')}catch{setError('Copy the invitation link from the field above.')}}}><Copy size={15}/>Copy</button></div></label>}<p className="quiet-note">This Site starts private to you. Before others can accept invitations, allow them to visit through the Site’s sharing controls. Group membership is also checked on every request.</p>{error&&<Notice>{error}</Notice>}{demo&&<p className="quiet-note">Invitation links are available in the hosted workspace.</p>}</ModalShell>}
function ImportForm({group:g,user,close,busy,error,save}:{group:Group;user:Workspace['user'];close:()=>void;busy:boolean;error:string;save:(p:any,n:string)=>Promise<void>}){const [records,setRecords]=useState<{id:string;description:string;date:string;amount:string;currency:string;selected:boolean}[]>([]),[localError,setError]=useState(''),[payer,setPayer]=useState(g.members.find(m=>m.userId===user.id)?.id||g.members[0].id);function parse(file:File){if(file.size>2*1024*1024){setError('Import a CSV smaller than 2 MB.');return}Papa.parse<Record<string,string>>(file,{header:true,skipEmptyLines:true,transformHeader:h=>h.trim().toLowerCase(),complete:r=>{if(r.errors.length){setError('CSV could not be read. Use the sample format below.');return}const next=r.data.slice(0,300).map(row=>({id:uuid(),description:row.description||row.merchant||'',date:row.date||today(),amount:String(Math.abs(Number((row.amount||'0').replace(/[$,]/g,'')))),currency:row.currency||g.currency,selected:true}));setRecords(next);setError('')},error:e=>setError(e.message)})}async function submit(e:FormEvent){e.preventDefault();try{const selected=records.filter(r=>r.selected);if(!selected.length)throw Error('Select at least one purchase.');const items=selected.map(r=>{if(r.currency!==g.currency)throw Error('Import one group-currency CSV at a time. Convert foreign transactions with the expense form.');return normalizeExpense({id:r.id,description:r.description,date:r.date,amount:cents(r.amount),currency:r.currency,payer,category:'Other',method:Object.keys(g.defaults).length?'shares':'equal',weights:Object.keys(g.defaults).length?g.defaults:Object.fromEntries(g.members.map(m=>[m.id,1])),items:[],notes:'Imported from CSV',repeat:'none',rate:1},g,user.id)});await save({action:'import',expenses:items},`${items.length} expenses imported.`)}catch(e){setError(err(e))}}return <ModalShell title="From your statement to shared." eyebrow="TRANSACTION IMPORT" onClose={close} wide><p className="dialog-description">Import purchases from a bank or card CSV. Required columns: <code>date,description,amount</code>. Optional: <code>currency</code>. Use ISO dates (YYYY-MM-DD). Amounts are treated as purchases; deselect income and refunds.</p><div className="import-tools"><label className="secondary"><FileUp size={16}/>Choose CSV<input type="file" accept=".csv,text/csv" hidden onChange={e=>{const f=e.target.files?.[0];if(f)parse(f);e.target.value=''}}/></label><button className="text-btn" onClick={()=>download('fairshare-import-template.csv',`date,description,amount,currency\n${today()},Dinner with friends,84.50,${g.currency}\n`,'text/csv')}><Download size={14}/>Sample CSV</button><label className="import-payer">Paid by<select value={payer} onChange={e=>setPayer(e.target.value)}>{g.members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label></div>{records.length>0&&<form onSubmit={submit}><div className="import-table">{records.map((r,i)=><div key={r.id}><input type="checkbox" aria-label={`Import row ${i+1}`} checked={r.selected} onChange={e=>setRecords(rows=>rows.map(x=>x.id===r.id?{...x,selected:e.target.checked}:x))}/><input aria-label={`Row ${i+1} date`} type="date" value={r.date} onChange={e=>setRecords(rows=>rows.map(x=>x.id===r.id?{...x,date:e.target.value}:x))}/><input aria-label={`Row ${i+1} description`} value={r.description} onChange={e=>setRecords(rows=>rows.map(x=>x.id===r.id?{...x,description:e.target.value}:x))}/><input aria-label={`Row ${i+1} amount`} type="number" min="0.01" step="0.01" value={r.amount} onChange={e=>setRecords(rows=>rows.map(x=>x.id===r.id?{...x,amount:e.target.value}:x))}/><span>{r.currency}</span></div>)}</div><div className="modal-footer"><span className="muted">{records.filter(r=>r.selected).length} selected · maximum 300</span><button className="primary" disabled={busy}>{busy?'Importing…':'Import selected purchases'}</button></div></form>}{(localError||error)&&<Notice>{localError||error}</Notice>}{!records.length&&<Empty title="Your purchases, all in one place." text="Choose a CSV to review and select transactions before importing."/>}</ModalShell>}

function GroupIcon({group:g}:{group:Group}){return g.icon?<img className="group-photo-icon" src={g.icon} alt=""/>:<span className="group-initials">{g.name.slice(0,2).toUpperCase()}</span>}
function ImageEditor({label,value,setValue,disabled,wide=false}:{label:string;value:string;setValue:(s:string)=>void;disabled:boolean;wide?:boolean}){const [error,setError]=useState('');async function choose(file:File){setError('');try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Choose a JPG, PNG or WebP under 10 MB.');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const ratio=Math.min(1,(wide?1400:256)/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const image=canvas.toDataURL('image/webp',.8);if(image.length>800000)throw Error('Try a smaller image.');setValue(image)}catch(e){setError(err(e))}}return <div className="image-editor"><label>{label}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={disabled} onChange={e=>{const f=e.target.files?.[0];if(f)choose(f)}}/></label>{value&&<><img className={wide?'banner-preview':'icon-preview'} src={value} alt={`${label} preview`}/><button type="button" className="text-btn" disabled={disabled} onClick={()=>setValue('')}>Remove {label.toLowerCase()}</button></>}{error&&<Notice>{error}</Notice>}<small>{wide?'Shown on the group card and group page.':'Shown in the sidebar and group headings.'} Images are resized before saving.</small></div>}
